export function FrameApp() {
  const [authenticated, setAuthenticated] = useState(!liveApiEnabled);
  const [authChecking, setAuthChecking] = useState(liveApiEnabled);
  const [mustChangePassword,setMustChangePassword]=useState(false);
  const [currentEmployee,setCurrentEmployee]=useState<Record<string,string>|null>(null);
  const [permissions,setPermissions]=useState<string[]>([]);
  const [dashboardMetrics,setDashboardMetrics]=useState<Record<string,unknown>|null>(null);
  const [loginPassword,setLoginPassword]=useState("");
  const [active, setActive] = useState<ModuleKey>("dashboard");
  const [tab, setTab] = useState(0);
  const [query, setQuery] = useState("");
  const [notice, setNotice] = useState("");
  const [menuOpen, setMenuOpen] = useState(false);
  const [selected, setSelected] = useState<Row | null>(null);
  const [liveRows, setLiveRows] = useState<Row[] | null>(null);
  const [loading, setLoading] = useState(false);
  const [creating, setCreating] = useState(false);
  const [editing, setEditing] = useState<Row|null>(null);
  const [searchResults,setSearchResults]=useState<Row[]>([]);
  const [notifications,setNotifications]=useState<Row[]|null>(null);
  const current = active === "dashboard" ? null : moduleData[active];
  const rows = useMemo(() => (liveRows ?? current?.rows ?? []).filter(row => Object.values(row).some(value => String(value).toLowerCase().includes(query.toLowerCase()))), [current, liveRows, query]);

  useEffect(() => { if (!liveApiEnabled) return; frameApi.me().then(result => {setAuthenticated(true);setCurrentEmployee(result.employee);setPermissions(result.permissions);setMustChangePassword(Boolean(result.employee.must_change_password));const requested=window.location.hash.slice(1) as ModuleKey;if(nav.some(item=>item.key===requested)&&modulePermissions[requested].some(permission=>result.permissions.includes(permission)))setActive(requested);}).catch(() => setAuthenticated(false)).finally(() => setAuthChecking(false)); }, []);
  useEffect(()=>{if(!liveApiEnabled||!authenticated||active!=="dashboard")return;let cancelled=false;frameApi.dashboard().then(value=>{if(!cancelled)setDashboardMetrics(value);}).catch(error=>flash(error.message));return()=>{cancelled=true;};},[active,authenticated]);
  useEffect(() => { if (!liveApiEnabled || !authenticated) return; const loaders:Partial<Record<ModuleKey,Array<()=>Promise<{data:Record<string,unknown>[]}>>>>={
    crm:[frameApi.customers,frameApi.customers,frameApi.customers,frameApi.customers],
    clients:[frameApi.contracts.list,frameApi.contracts.list,frameApi.services.list,frameApi.clientReports.list,frameApi.complaints.list],
    operations:[frameApi.tasks,frameApi.tasks,frameApi.meetings.list,frameApi.meetings.list,frameApi.dailyReports.list],
    performance:[frameApi.kpis.list,frameApi.weeklyKpi,frameApi.tasks,frameApi.kpis.list],
    hr:[frameApi.employees,frameApi.attendanceEntries,frameApi.leave.list,frameApi.discipline.list,frameApi.recruitment.list,frameApi.employeeExits],
    finance:[frameApi.reports,frameApi.invoices.list,frameApi.expenses.list,frameApi.payroll.list,frameApi.budgets.list,frameApi.accounting],
    assets:[frameApi.assets.list,frameApi.assetRequests.list,frameApi.assets.list,frameApi.assets.list],
    procurement:[frameApi.procurement.list,frameApi.suppliers.list,frameApi.subscriptions.list],
    approvals:[()=>frameApi.approvals("mine"),()=>frameApi.approvals("submitted"),()=>frameApi.approvals("completed"),()=>frameApi.approvals("all")],
    reports:[frameApi.reports,frameApi.reports,frameApi.clientReports.list,frameApi.attendanceEntries,frameApi.reports,frameApi.audit],
    administration:[frameApi.departments,frameApi.roles,frameApi.roleAssignments,frameApi.permissions,frameApi.services.list,frameApi.attendanceNetworks.list,frameApi.attendanceSchedules.list],
  };const loader=loaders[active]?.[tab]??loaders[active]?.[0];if(!loader)return;let cancelled=false;queueMicrotask(()=>{if(!cancelled)setLoading(true);});loader().then(result=>{if(!cancelled)setLiveRows(mapApiRows(active,result.data,tab));}).catch(error=>{if(!cancelled){setLiveRows([]);flash(error.message);}}).finally(()=>{if(!cancelled)setLoading(false);});return()=>{cancelled=true;};},[active,tab,authenticated]);
  useEffect(()=>{if(!liveApiEnabled||query.trim().length<2){const clear=window.setTimeout(()=>setSearchResults([]),0);return()=>window.clearTimeout(clear);}const timer=window.setTimeout(()=>{frameApi.search(query).then(result=>setSearchResults(result.data.map(item=>({_id:String(item.id),Type:String(item.type),Reference:String(item.reference),Label:String(item.label)})))).catch(()=>setSearchResults([]));},250);return()=>window.clearTimeout(timer);},[query]);

  const allowedNav=liveApiEnabled?nav.filter(item=>modulePermissions[item.key].some(permission=>permissions.includes(permission))):nav;
  function go(key: ModuleKey) { if(liveApiEnabled&&!modulePermissions[key].some(permission=>permissions.includes(permission)))return;setActive(key); setTab(0); setQuery(""); setLiveRows(null); setMenuOpen(false); window.location.hash = key; }
  function flash(message: string) { setNotice(message); window.setTimeout(() => setNotice(""), 2800); }

  if (authChecking) return <main className="auth-loading"><div className="login-logo">F</div><p>Securing your FRAME workspace…</p></main>;
  if (!authenticated) return <LoginScreen onLogin={async(employeeId,password) => { const result=await frameApi.login(employeeId,password);const access=await frameApi.me();setLoginPassword(password);setMustChangePassword(result.mustChangePassword);setCurrentEmployee(access.employee);setPermissions(access.permissions);setAuthenticated(true);const first=nav.find(item=>modulePermissions[item.key].some(permission=>access.permissions.includes(permission)))?.key??"dashboard";setActive(first);window.location.hash=first; }} />;
  return <main className="app-shell">
    <aside className={`sidebar ${menuOpen ? "open" : ""}`}>
      <div className="brand"><span className="brand-mark">F</span><div><strong>FRAME</strong><small>OPERATING SYSTEM</small></div><button className="close-menu" onClick={() => setMenuOpen(false)}>×</button></div>
      <nav aria-label="Primary navigation"><p className="nav-label">Workspace</p>{allowedNav.map(item => <button className={active === item.key ? "nav-item active" : "nav-item"} onClick={() => go(item.key)} key={item.key}><span>{item.icon}</span>{item.label}{item.badge ? <b>{item.badge}</b> : null}</button>)}</nav>
      <div className="sidebar-footer"><div className="avatar">{currentEmployee?`${currentEmployee.first_name?.[0]??""}${currentEmployee.last_name?.[0]??""}`:"AN"}</div><div><strong>{currentEmployee?`${currentEmployee.first_name} ${currentEmployee.last_name}`:"Amir Noor"}</strong><small>{currentEmployee?.employee_number??"Chief Executive Officer"}</small></div><button onClick={async() => { if(liveApiEnabled) await frameApi.logout(); setAuthenticated(false); }} aria-label="Sign out">↪</button></div>
    </aside>
    <section className="workspace">
      <header className="topbar"><button className="mobile-menu" onClick={() => setMenuOpen(true)}>☰</button><div className="search-wrap"><label className="search"><span>⌕</span><input value={query} onChange={event => setQuery(event.target.value)} placeholder="Search this workspace…" /><kbd>⌘ K</kbd></label>{searchResults.length?<div className="search-results">{searchResults.map(row=><button key={String(row._id)} onClick={()=>{setSelected(row);setQuery("");setSearchResults([]);}}><b>{row.Type}</b><span>{row.Label}</span><small>{row.Reference}</small></button>)}</div>:null}</div><div className="top-actions"><button onClick={async()=>{if(liveApiEnabled){try{const result=await frameApi.notifications();setNotifications(result.data.map(item=>({_id:String(item.id),Title:String(item.title),Message:String(item.body),Priority:String(item.priority),Created:new Date(String(item.created_at)).toLocaleString("en-RW")})));}catch(error){flash(error instanceof Error?error.message:"Notifications unavailable");}}else setNotifications([{Title:"Approval required",Message:"August payroll is waiting for review",Priority:"High",Created:"Today"}]);}}>♢<i>5</i></button><button className="attendance-button" onClick={async()=>{try{if(liveApiEnabled)await frameApi.attendance("check-in");flash("Attendance check-in recorded");}catch(error){flash(error instanceof Error?error.message:"Check-in failed");}}}>Check in</button><button className="attendance-button" onClick={async()=>{try{if(liveApiEnabled)await frameApi.attendance("check-out");flash("Attendance check-out recorded");}catch(error){flash(error instanceof Error?error.message:"Check-out failed");}}}>Check out</button>{canCreate(active,tab,permissions)?<button className="create" onClick={() => setCreating(true)}>＋ Create</button>:null}</div></header>
      {active === "dashboard" ? <Dashboard go={go} flash={flash} live={dashboardMetrics} /> : current ? <ModulePage data={current} rows={rows} loading={loading} tab={tab} setTab={setTab} setSelected={setSelected} flash={flash} onCreate={() => setCreating(true)} canCreate={canCreate(active,tab,permissions)} /> : null}
    </section>
    {notice ? <div className="toast">✓ {notice}</div> : null}
    {selected ? active==="administration"&&tab===1?<RolePermissionDrawer row={selected} close={()=>setSelected(null)} flash={flash} onSaved={permissions=>setLiveRows(current=>current?.map(row=>row._id===selected._id?{...row,Manager:`${permissions.length} permissions`,_permissions:JSON.stringify(permissions)}:row)??null)}/>:<RecordDrawer row={selected} close={() => setSelected(null)} flash={flash} onResetPassword={active==="hr"&&tab===0&&permissions.includes("employees.reset_password")?()=>frameApi.resetEmployeePassword(String(selected._id)):undefined} onDeactivate={active==="hr"&&tab===0&&permissions.includes("employees.deactivate")?async reason=>{await frameApi.deactivateEmployee(String(selected._id),reason);setLiveRows(current=>current?.map(row=>row._id===selected._id?{...row,Status:"suspended"}:row)??null);}:undefined} onDelete={active==="hr"&&tab===0&&permissions.includes("employees.delete")?async()=>{await frameApi.deleteEmployee(String(selected._id));setLiveRows(current=>current?.filter(row=>row._id!==selected._id)??null);}:undefined} onEdit={active==="hr"&&tab===0&&permissions.includes("employees.sensitive")&&permissions.includes("employees.edit")?()=>{setEditing(selected);setSelected(null);}:editConfig(active,tab)?()=>{setEditing(selected);setSelected(null);}:undefined} onDecision={active === "approvals" && liveApiEnabled ? async decision => { await frameApi.decideApproval(String(selected._id),decision); setLiveRows(current => current?.filter(row => row._id !== selected._id) ?? null); } : undefined} /> : null}
    {creating ? <CreateDrawer module={active} tab={tab} close={() => setCreating(false)} flash={flash} onCreated={() => { setCreating(false); if(liveApiEnabled){setAuthenticated(value=>value);setLiveRows(null);const currentActive=active;setActive("dashboard");queueMicrotask(()=>setActive(currentActive));} }} /> : null}
    {editing?active==="hr"&&tab===0?<EmployeeProfileDrawer row={editing} close={()=>setEditing(null)} flash={flash} onSaved={()=>{setEditing(null);const currentActive=active;setActive("dashboard");queueMicrotask(()=>setActive(currentActive));}}/>:<EditDrawer module={active} tab={tab} row={editing} close={()=>setEditing(null)} flash={flash} onSaved={()=>{setEditing(null);const currentActive=active;setActive("dashboard");queueMicrotask(()=>setActive(currentActive));}}/>:null}
    {mustChangePassword?<PasswordChange currentPassword={loginPassword} complete={()=>{setMustChangePassword(false);setLoginPassword("");}}/>:null}
    {notifications?<NotificationDrawer rows={notifications} close={()=>setNotifications(null)} flash={flash}/>:null}
    {menuOpen ? <button className="scrim" onClick={() => setMenuOpen(false)} aria-label="Close navigation" /> : null}
  </main>;
}

function NotificationDrawer({rows,close,flash}:{rows:Row[];close:()=>void;flash:(m:string)=>void}){return <><button className="drawer-scrim" onClick={close}/><aside className="record-drawer"><div className="drawer-head"><div><p className="eyebrow">Inbox</p><h2>Notifications</h2></div><button onClick={close}>×</button></div><div className="notification-list">{rows.length?rows.map((row,index)=><button key={String(row._id??index)} onClick={async()=>{if(liveApiEnabled&&row._id)await frameApi.readNotification(String(row._id));flash("Notification marked as read");}}><b>{row.Title}</b><span>{row.Message}</span><small>{row.Priority} • {row.Created}</small></button>):<p>No notifications.</p>}</div></aside></>}

function PasswordChange({currentPassword,complete}:{currentPassword:string;complete:()=>void}){const [current,setCurrent]=useState(currentPassword);const [password,setPassword]=useState("");const [confirm,setConfirm]=useState("");const [error,setError]=useState("");const [saving,setSaving]=useState(false);async function submit(event:React.FormEvent){event.preventDefault();if(password!==confirm){setError("Passwords do not match");return;}setSaving(true);try{await frameApi.changePassword(current,password);complete();}catch(caught){setError(caught instanceof Error?caught.message:"Password change failed");}finally{setSaving(false);}}return <div className="mandatory-modal"><form onSubmit={submit}><div className="login-logo">F</div><p className="eyebrow">Required security step</p><h2>Create your permanent password</h2><span>Your temporary password cannot be used again after this change.</span>{!currentPassword?<label>Temporary password<input type="password" required value={current} onChange={event=>setCurrent(event.target.value)}/></label>:null}<label>New password<input type="password" minLength={12} required value={password} onChange={event=>setPassword(event.target.value)}/></label><label>Confirm password<input type="password" minLength={12} required value={confirm} onChange={event=>setConfirm(event.target.value)}/></label>{error?<p className="login-error">{error}</p>:null}<button disabled={saving}>{saving?"Saving…":"Set permanent password"}</button></form></div>}

function mapApiRows(module: ModuleKey, data: Record<string,unknown>[], tab=0): Row[] {
  const generic=()=>data.map(item=>Object.fromEntries([["_id",String(item.id)],...Object.entries(item).filter(([key])=>key!=="id").map(([key,value])=>[key.split("_").map(part=>part.charAt(0).toUpperCase()+part.slice(1)).join(" "),value==null?"—":typeof value==="object"?JSON.stringify(value):String(value)])]) as Row);
  if(module==="administration"&&tab===1)return data.map(item=>{const permissions=Array.isArray(item.permissions)?item.permissions:[];return{_id:String(item.id),Department:String(item.name),Code:String(item.description??"—"),Manager:`${permissions.length} permissions`,Employees:"—","Open work":"Open to configure",Status:String(item.status),_permissions:JSON.stringify(permissions)};});
  if(module==="administration"&&tab===2)return data.map(item=>({_id:String(item.id),Department:String(item.employee),Code:String(item.employee_number),Manager:String(item.role),Employees:String(item.department),"Open work":new Date(String(item.valid_from)).toLocaleDateString("en-RW"),Status:"Active"}));
  if(module==="administration"&&tab===3)return data.map(item=>({_id:String(item.permission_key),Department:String(item.permission_key),Code:String(item.description??"—"),Manager:"System permission",Employees:"—","Open work":"—",Status:"Available"}));
  if(module==="hr"&&tab===2)return data.map(item=>({_id:String(item.id),"Employee ID":String(item.employee_number),Employee:String(item.employee),Department:String(item.leave_type).replaceAll("_"," "),Manager:`${item.total_days} working day${Number(item.total_days)===1?"":"s"}`,Attendance:`${new Date(String(item.starts_on)).toLocaleDateString("en-RW")} – ${new Date(String(item.ends_on)).toLocaleDateString("en-RW")}`,Status:String(item.status),_reason:String(item.reason),_available:String(item.available_days)}));
  if(tab>0&&moduleData[module as Exclude<ModuleKey,"dashboard">])return generic();
  if(module==="crm")return data.map(item=>({_id:String(item.id),Reference:String(item.customer_number),Customer:String(item.business_name),Stage:String(item.status),Owner:String(item.owner??"Unassigned"),Value:item.value?`RWF ${Number(item.value).toLocaleString("en-RW")}`:"—","Next action":item.next_follow_up_at?new Date(String(item.next_follow_up_at)).toLocaleDateString("en-RW"):"Not scheduled"}));
  if(module==="operations")return data.map(item=>({_id:String(item.id),Task:String(item.title),Client:String(item.client??"Internal"),Assignee:String(item.assignee),Deadline:new Date(String(item.deadline)).toLocaleString("en-RW"),Progress:`${item.progress}%`,Status:String(item.status).replaceAll("_"," ")}));
  if(module==="clients")return data.map(item=>({_id:String(item.id),Contract:String(item.contract_number),Client:String(item.client),Package:String(item.package??"Custom"),"Account manager":String(item.account_manager??"Unassigned"),"End date":new Date(String(item.ends_on)).toLocaleDateString("en-RW"),Status:String(item.status)}));
  if(module==="performance")return data.map(item=>({_id:String(item.id),Employee:String(item.employee),Department:String(item.department??"Unassigned"),Plan:new Date(String(item.month)).toLocaleDateString("en-RW",{month:"long",year:"numeric"}),Evidence:"—",Score:item.final_score?`${item.final_score}%`:"—",Status:String(item.status)}));
  if(module==="hr")return data.map(item=>({_id:String(item.id),"Employee ID":String(item.employee_number),Employee:`${item.first_name} ${item.last_name}`,Department:String(item.department??"Unassigned"),Manager:String(item.manager_number??"—"),Attendance:"—",Status:String(item.status)}));
  if(module==="administration")return data.map(item=>({_id:String(item.id),Department:String(item.name),Code:String(item.code),Manager:"—",Employees:"—","Open work":"—",Status:String(item.status)}));
  if(module==="finance")return data.map(item=>({_id:String(item.id),Reference:String(item.id).slice(0,8).toUpperCase(),Description:String(item.description),Account:String(item.department),"Due date":"—",Amount:`${item.currency} ${Number(item.amount).toLocaleString("en-RW")}`,Status:String(item.status)}));
  if(module==="assets")return data.map(item=>({_id:String(item.id),"Asset ID":String(item.asset_number),Asset:String(item.name),Category:String(item.category),"Assigned to":String(item.assigned_to??"—"),Condition:String(item.condition),Status:String(item.status)}));
  if(module==="procurement")return data.map(item=>({_id:String(item.id),Reference:String(item.request_number),Request:String(item.description),Department:String(item.department),Supplier:String(item.supplier??"—"),Amount:`${item.currency} ${Number(item.amount).toLocaleString("en-RW")}`,Status:String(item.status)}));
  if(module==="approvals")return data.map(item=>({_id:String(item.id),Type:String(item.entity_type),Request:String(item.title),"Submitted by":String(item.requested_by),"Current step":String(item.step_number),Value:"—",Age:item.submitted_at?new Date(String(item.submitted_at)).toLocaleDateString("en-RW"):"—"}));
  if(module==="reports")return generic();
  return [];
}

function LoginScreen({ onLogin }: { onLogin: (employeeId:string,password:string) => Promise<void> }) {
  const [employeeId, setEmployeeId] = useState("FRM-0001");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");
  const [submitting,setSubmitting]=useState(false);
  async function submit(event: React.FormEvent) { event.preventDefault(); if (!employeeId.trim() || !password) { setError("Enter your employee ID and password."); return; } setSubmitting(true);setError("");try{await onLogin(employeeId,password);}catch(error){setError(error instanceof Error?error.message:"Sign in failed");}finally{setSubmitting(false);} }
  return <main className="login-page"><section className="login-brand"><div className="login-logo">F</div><p>FRAME MEDIA AGENCY</p><h1>One system.<br/>Every operation.</h1><span>CRM, delivery, people, performance and finance in one controlled workspace.</span><div className="login-proof"><b>Protected</b><b>Audited</b><b>Permission-based</b></div></section><section className="login-card"><form onSubmit={submit}><p className="eyebrow">FRAME OPERATING SYSTEM</p><h2>Welcome back</h2><span>Sign in using your FRAME employee account.</span><label>Employee ID<input value={employeeId} onChange={event => setEmployeeId(event.target.value.toUpperCase())} autoComplete="username" placeholder="FRM-0001"/></label><label>Password<input type="password" value={password} onChange={event => setPassword(event.target.value)} autoComplete="current-password"/></label>{error ? <p className="login-error">{error}</p> : null}<button type="submit" disabled={submitting}>{submitting?"Signing in…":"Sign in to FRAME OS"}</button><small>Production access uses encrypted passwords, secure sessions and rate limiting.</small></form></section></main>;
}

async function createAndDownloadReport(reportKey:string,format:"pdf"|"xlsx",progress:(message:string)=>void,filters:Record<string,unknown>={}){const created=await frameApi.exportReport(reportKey,format,filters);const id=created.data.id;progress(`Preparing ${format.toUpperCase()} report…`);for(let attempt=0;attempt<60;attempt++){const result=await frameApi.exportStatus(id);if(result.data.status==="completed"){const link=document.createElement("a");link.href=frameApi.exportDownloadUrl(id);link.download="";document.body.appendChild(link);link.click();link.remove();progress(`${format.toUpperCase()} report downloaded`);return;}if(result.data.status==="failed")throw new Error("Report generation failed");await new Promise(resolve=>window.setTimeout(resolve,2000));}throw new Error("Report is still processing. Try again shortly.");}

function Dashboard({ go, flash,live }: { go: (key: ModuleKey) => void; flash: (message: string) => void;live?:Record<string,unknown>|null }) {
  const scope=String(live?.scope??"company");const shown=live?(scope==="self"?[{label:"Assigned tasks",value:String(live.assignedTasks),change:"Mine",tone:"blue"},{label:"My KPI score",value:`${live.kpiScore}%`,change:"Mine",tone:"green"},{label:"Attendance today",value:live.attendanceToday?"Recorded":"Not recorded",change:"Today",tone:"green"},{label:"Pending leave",value:String(live.pendingLeave),change:"Mine",tone:"amber"}]:scope==="department"?[{label:"Department tasks",value:String(live.openTasks),change:"Department",tone:"blue"},{label:"Department KPI",value:`${live.kpiScore}%`,change:"Department",tone:"green"},{label:"Active staff",value:String(live.activeEmployees),change:"Department",tone:"green"},{label:"Pending leave",value:String(live.pendingLeave),change:"Department",tone:"amber"}]:[{label:"Active clients",value:String(live.activeClients),change:"Live",tone:"green"},{label:"Open tasks",value:String(live.openTasks),change:"Live",tone:"blue"},{label:"Pending approvals",value:String(live.pendingApprovals),change:"Live",tone:"amber"},{label:"Active employees",value:String(live.activeEmployees),change:"Live",tone:"green"}]):metrics;
  return <div className="content"><div className="heading-row"><div><p className="eyebrow">{new Intl.DateTimeFormat("en-RW",{weekday:"long",day:"numeric",month:"long",year:"numeric"}).format(new Date())}</p><h1>Command center</h1><p>{scope==="self"?"Your assigned work, attendance, leave and performance.":"A live view of performance, work and risk."}</p></div><div className="heading-actions export-actions"><button onClick={async()=>{try{await createAndDownloadReport("executive","xlsx",flash);}catch(error){flash(error instanceof Error?error.message:"Excel export failed");}}}>Excel</button><button onClick={async()=>{try{await createAndDownloadReport("executive","pdf",flash);}catch(error){flash(error instanceof Error?error.message:"PDF export failed");}}}>PDF</button><button className="primary" onClick={() => go("approvals")}>Review approvals <span>{String(live?.pendingApprovals??0)}</span></button></div></div>
    <section className="metric-grid">{shown.map(metric => <article className="metric" key={metric.label}><div className="metric-label"><span>{metric.label}</span><button>•••</button></div><strong>{metric.value}</strong><p><em className={metric.tone}>{metric.change}</em> vs last month</p></article>)}</section>
    {scope==="self"?<section className="panel"><div className="panel-head"><div><h2>My workspace</h2><p>Your dashboard contains only your assigned work, attendance, leave and KPI information.</p></div></div></section>:<div className="dashboard-grid"><section className="panel performance-panel"><div className="panel-head"><div><h2>{scope==="department"?"Department performance":"Revenue performance"}</h2><p>{scope==="department"?"Department workload and KPI summary":"Actual revenue against monthly target"}</p></div><select><option>Last 6 months</option></select></div><div className="chart-wrap"><div className="chart-y"><span>150k</span><span>100k</span><span>50k</span><span>0</span></div><div className="chart"><div className="target-line"><span>Target</span></div><div className="bars">{[68,74,62,81,72,86].map((height,index) => <div className="bar-column" key={index}><div className={index === 5 ? "bar current" : "bar"} style={{height:`${height}%`}}/><span>{["Mar","Apr","May","Jun","Jul","Aug"][index]}</span></div>)}</div></div></div></section>
      <section className="panel risk-panel"><div className="panel-head"><div><h2>Operational pulse</h2><p>Items requiring attention</p></div><button onClick={() => go("operations")}>View all</button></div><div className="risk-list">{[["red","!","9 overdue tasks","3 became failed today","High"],["amber","↻","6 contracts expiring","Within the next 7 days","Review"],["blue","◷","4 missing reports","Yesterday's daily reports","Follow up"],["violet","△","2 budgets over limit","Production and Content","Approve"]].map(item => <div key={item[2]}><span className={`risk-icon ${item[0]}`}>{item[1]}</span><p><strong>{item[2]}</strong><small>{item[3]}</small></p><b>{item[4]}</b></div>)}</div></section>
      <section className="panel approvals-panel"><div className="panel-head"><div><h2>Pending approvals</h2><p>Waiting for your decision</p></div><button onClick={() => go("approvals")}>Open approval center →</button></div><div className="approval-table">{moduleData.approvals.rows.slice(0,3).map(row => <div className="approval-row" key={String(row.Request)}><span className="type-chip">{row.Type}</span><p><strong>{row.Request}</strong><small>{row["Submitted by"]}</small></p><strong>{row.Value}</strong><time>{row.Age}</time><button onClick={() => go("approvals")}>Review</button></div>)}</div></section>
      <section className="panel activity-panel"><div className="panel-head"><div><h2>Management activity</h2><p>Recent high-impact actions</p></div><button onClick={() => go("reports")}>Audit log →</button></div><div className="timeline">{[["Contract FRM-CON-0184 approved","General Manager • Northstar Retail","09:42"],["Lead reassigned to Leila Hassan","Sales Manager • FRM-CUS-000184","09:18"],["Payroll batch submitted","HR • August 2026","08:55"]].map((item,index) => <div key={item[0]}><span className={index===0?"timeline-dot active":"timeline-dot"}/><p><strong>{item[0]}</strong><small>{item[1]}</small></p><time>{item[2]}</time></div>)}</div></section>
    </div>}</div>;
}

function ModulePage({ data, rows, loading, tab, setTab, setSelected, flash, onCreate, canCreate }: { data: typeof moduleData.crm; rows: Row[]; loading:boolean; tab: number; setTab: (n:number)=>void; setSelected:(row:Row)=>void; flash:(m:string)=>void; onCreate:()=>void;canCreate:boolean }) {
  const columns=rows.length?Object.keys(rows[0]).filter(column=>!column.startsWith("_")):data.columns;
  const reportKey=({"CRM & Sales":"sales","Clients & Contracts":"clients","Operations":"operations","Performance & KPI":"tasks","People & HR":"people","Finance & Accounting":"finance","Assets":"assets","Procurement":"procurement","Approvals":"audit","Reports & Audit":"audit","Administration":"employees"} as Record<string,string>)[data.title]??"audit";
  async function exportRows(format:"pdf"|"xlsx"){try{if(liveApiEnabled)await createAndDownloadReport(reportKey,format,flash);else flash(`${format.toUpperCase()} report ready`);}catch(error){flash(error instanceof Error?error.message:"Export failed");}}
  return <div className="content module-content"><div className="heading-row"><div><p className="eyebrow">FRAME OS workspace</p><h1>{data.title}</h1><p>{data.subtitle}</p></div><div className="heading-actions export-actions"><button onClick={()=>exportRows("xlsx")}>Excel</button><button onClick={()=>exportRows("pdf")}>PDF</button>{canCreate?<button className="primary" onClick={onCreate}>＋ {data.action}</button>:null}</div></div>
    <div className="module-stats"><div><small>Total records</small><strong>{rows.length}</strong><em>Live</em></div><div><small>Needs attention</small><strong>{rows.filter(row=>/pending|overdue|failed|expired|missing|review/i.test(String(row.Status??row.Stage??""))).length}</strong><em className="warn">Review</em></div><div><small>Completed or active</small><strong>{rows.filter(row=>/completed|active|approved|ready|paid|delivered/i.test(String(row.Status??row.Stage??""))).length}</strong><em>Current</em></div><div><small>Other records</small><strong>{rows.filter(row=>!/completed|active|approved|ready|paid|delivered|pending|overdue|failed|expired|missing|review/i.test(String(row.Status??row.Stage??""))).length}</strong><em className="warn">Open</em></div></div>
    <section className="panel data-panel"><div className="tabbar" role="tablist">{data.tabs.map((name,index) => <button role="tab" aria-selected={tab===index} className={tab===index?"selected":""} onClick={() => setTab(index)} key={name}>{name}</button>)}</div><div className="table-toolbar"><div><button className="filter-button">☷ Filter</button><span>{loading?"Loading live records…":`${rows.length} shown`}</span></div><button onClick={() => flash("View preferences saved")}>Columns ⚙</button></div><div className="table-scroll"><table><thead><tr>{columns.map(column => <th key={column}>{column}</th>)}<th></th></tr></thead><tbody>{rows.map((row,index) => <tr key={String(row._id??index)} onClick={() => setSelected(row)}>{columns.map(column => <td key={column}>{column === "Status" || column === "Stage" ? <span className={`status status-${String(row[column]).toLowerCase().replaceAll(" ","-")}`}>{row[column]}</span> : row[column]}</td>)}<td><button>›</button></td></tr>)}</tbody></table>{!loading&&rows.length===0?<div className="empty-state"><strong>No matching records</strong><p>Try a different search term.</p></div>:null}</div></section>
  </div>;
}

